struct MaxFlowSolver {
    int cap[MAXN][MAXN], flow[MAXN][MAXN], adj[MAXN][MAXN], degree[MAXN];
    int totalNodes, s, t;
    int height[MAXN], countH[MAXN];

    void init(int n) {
        totalNodes = n;
        memset(cap, 0, sizeof(cap));
        memset(adj, 0, sizeof(adj));
        for (int i = 0; i <= n; i++) degree[i] = 0;
        memset(height, 0, sizeof(height));
        memset(countH, 0, sizeof(countH));
