        for (int v = 0; v < totalNodes; v++) {
            if (cap[u][v] - flow[u][v] > 0 && height[u] == height[v] + 1) {
                int pushed = min(flowIn, cap[u][v] - flow[u][v]);
                int pushedAmount = augment(v, pushed);
                if (pushedAmount > 0) {
                    flow[u][v] += pushedAmount;
                    flow[v][u] -= pushedAmount;
                    totalFlow += pushedAmount;
                    flowIn -= pushedAmount;
                    if (flowIn == 0) break;
                }
            }
        }
        if (totalFlow == 0) {
            int minH = totalNodes;
            for (int v = 0; v < totalNodes; v++) {
                if (cap[u][v] - flow[u][v] > 0) minH = min(minH, height[v]);
            }
            if (--countH[height[u]] == 0) height[s] = totalNodes;
            height[u] = minH + 1;
            countH[height[u]]++;
        }
        return totalFlow;
    }

    int maxFlow(int s_, int t_) {
        s = s_; t = t_;
        memset(flow, 0, sizeof(flow));
        memset(height, 0, sizeof(height));
        memset(countH, 0, sizeof(countH));
        for (int i = 0; i <= totalNodes; i++) height[i] = 0;
        countH[0] = totalNodes;
        int totalFlow = 0;
        while (height[s] < totalNodes) {
            totalFlow += augment(s, INF);
        }
        return totalFlow;
    }
};

