class MaxFlowSolver:
    def __init__(self, n):
        self.MAXN = n
        self.INF = 10**9
        self.cap = [[0]*(self.MAXN) for _ in range(self.MAXN)]
        self.flow = [[0]*(self.MAXN) for _ in range(self.MAXN)]
        self.adj = [[0]*(self.MAXN) for _ in range(self.MAXN)]
        self.degree = [0]*(self.MAXN)
        self.totalNodes = n
        self.s = 0
        self.t = 0
        self.height = [0]*self.MAXN
        self.countH = [0]*(self.MAXN)

    def init(self, n):
        self.totalNodes = n
        for i in range(n):
            for j in range(n):
                self.cap[i][j] = 0
                self.flow[i][j] = 0
                self.adj[i][j] = 0
        for i in range(n):
            self.degree[i] = 0
        for i in range(n):
            self.height[i] = 0
        for i in range(n):
            self.countH[i] = 0

    def addEdge(self, u, v, c):
        self.cap[u][v] += c
        if self.adj[u][v] == 0:
            self.adj[u][v] = 1
            self.degree[u] += 1

    def augment(self, u, flowIn):
        if u == self.t:
            return flowIn
        totalFlow = 0
        for v in range(self.totalNodes):
            if self.cap[u][v] - self.flow[u][v] > 0 and self.height[u] == self.height[v] + 1:
                pushed = min(flowIn, self.cap[u][v] - self.flow[u][v])
                pushedAmount = self.augment(v, pushed)
                if pushedAmount > 0:
                    self.flow[u][v] += pushedAmount
                    self.flow[v][u] -= pushedAmount
                    totalFlow += pushedAmount
                    flowIn -= pushedAmount
                    if flowIn == 0:
                        break
        if totalFlow == 0:
            minH = self.totalNodes
            for v in range(self.totalNodes):
                if self.cap[u][v] - self.flow[u][v] > 0:
                    minH = min(minH, self.height[v])
            self.countH[self.height[u]] -= 1
            if self.countH[self.height[u]] == 0:
                self.height[self.s] = self.totalNodes
            self.height[u] = minH + 1
            self.countH[self.height[u]] += 1
        return totalFlow

    def maxFlow(self, s_, t_):
        self.s = s_
        self.t = t_
        for i in range(self.totalNodes):
            for j in range(self.totalNodes):
                self.flow[i][j] = 0
        for i in range(self.totalNodes):
            self.height[i] = 0
        for i in range(self.totalNodes):
            self.countH[i] = 0
        for i in range(self.totalNodes):
            self.height[i] = 0
        self.countH[0] = self.totalNodes
        totalFlow = 0
        while self.height[self.s] < self.totalNodes:
            totalFlow += self.augment(self.s, self.INF)
        return totalFlow

