import sys
from collections import deque

n, T = map(int, sys.stdin.readline().split())
mazeA = [list(sys.stdin.readline().strip()) for _ in range(n)]
mazeB = [list(sys.stdin.readline().strip()) for _ in range(n)]

startX, startY = 0, 0

dirX = [0, 0, -1, 1]
dirY = [-1, 1, 0, 0]

def getID(i, j):
    return (i - 1) * n + j

def valid(x, y):
    return 0 <= x < n and 0 <= y < n

distMap = [[float('inf')] * n for _ in range(n)]
visited = [[0] * n for _ in range(n)]

def BFS1():
    q = deque()
    c = Cell(startX, startY, 0)
    q.append(c)
    for i in range(n):
        for j in range(n):
            distMap[i][j] = float('inf')
            visited[i][j] = 0
    visited[startX][startY] = 1
    while q:
        c = q.popleft()
        distMap[c.r][c.c] = c.d
        if c.d > T:
            break
        for k in range(4):
            nx = c.r + dirX[k]
            ny = c.c + dirY[k]
            if valid(nx, ny) and mazeA[nx][ny] != 'Y' and not visited[nx][ny]:
                nc = Cell(nx, ny, c.d + 1)
                visited[nx][ny] = 1
                q.append(nc)

def BFS2(i, j):
    q = deque()
    c = Cell(i, j, 0)
    for x in range(n):
        for y in range(n):
            visited[x][y] = 0
    visited[i][j] = 1
    q.append(c)
    while q:
        c = q.popleft()
        if c.d > T:
            break
        if distMap[c.r][c.c] < c.d:
            continue
        if (distMap[c.r][c.c] == c.d and mazeB[c.r][c.c] < '1') or mazeB[c.r][c.c] > '9':
            continue
        if '1' <= mazeB[c.r][c.c] <= '9':
            if c.r != i or c.c != j:
                solver.addEdge(getID(i, j), getID(c.r, c.c) + n * n, solver.INF)
            if distMap[c.r][c.c] == c.d:
                continue
        for k in range(4):
            nx = c.r + dirX[k]
            ny = c.c + dirY[k]
            if valid(nx, ny) and mazeA[nx][ny] != 'Y' and not visited[nx][ny]:
                nc = Cell(nx, ny, c.d + 1)
                visited[nx][ny] = 1
                q.append(nc)

def main():
    global solver
    total_nodes = 2 * n * n + 2
    s = 0
    e = 2 * n * n + 1
    solver = MaxFlowSolver(total_nodes)
    solver.init(total_nodes)
    for i in range(n):
        for j in range(n):
            if mazeA[i][j] >= '1' and mazeA[i][j] <= '9':
                solver.addEdge(s, getID(i, j), ord(mazeA[i][j]) - ord('0'))
            if mazeA[i][j] == 'Z':
                nonlocal startX, startY
                startX, startY = i, j
    for i in range(n):
        for j in range(n):
            solver.addEdge(getID(i, j), getID(i, j) + n * n, solver.INF)
            if mazeB[i][j] >= '1' and mazeB[i][j] <= '9':
                solver.addEdge(getID(i, j) + n * n, e, ord(mazeB[i][j]) - ord('0'))
    BFS1()
    for i in range(n):
        for j in range(n):
            if mazeA[i][j] >= '1' and mazeA[i][j] <= '9':
                BFS2(i, j)
    res = solver.maxFlow(s, e)
    print(res)

if __name__ == "__main__":
    main()

